namespace sv_f586a0f00ea34dafb36bbe1bd8901ceb.Client.Models;

public sealed class StatusUpdate
{
    public required DateTime Timestamp { get; init; }
    public required string Status { get; init; }
    public required string Location { get; init; }
}

public sealed class Shipment
{
    public required string TrackingNumber { get; init; }
    public required string Status { get; init; }
    public required string Location { get; init; }
    public required DateTime EstimatedDelivery { get; init; }
    public required List<StatusUpdate> Updates { get; init; }
}

using sv_f586a0f00ea34dafb36bbe1bd8901ceb.Client.Models;

namespace sv_f586a0f00ea34dafb36bbe1bd8901ceb.Client.Services;

public interface IShipmentService
{
    Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using System.Net.Http.Json;
using sv_f586a0f00ea34dafb36bbe1bd8901ceb.Client.Models;

namespace sv_f586a0f00ea34dafb36bbe1bd8901ceb.Client.Services;

public sealed class HttpShipmentService(HttpClient http) : IShipmentService
{
    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<Shipment>(ct);
    }
}

using sv_f586a0f00ea34dafb36bbe1bd8901ceb.Client.Models;
using sv_f586a0f00ea34dafb36bbe1bd8901ceb.Client.Services;

namespace sv_f586a0f00ea34dafb36bbe1bd8901ceb.Services;

public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> Seeds = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-1001"] = new Shipment
        {
            TrackingNumber = "TRK-1001",
            Status = "In Transit",
            Location = "Memphis, TN",
            EstimatedDelivery = new DateTime(2026, 6, 7, 17, 0, 0, DateTimeKind.Utc),
            Updates =
            [
                new StatusUpdate { Timestamp = new DateTime(2026, 6, 1, 8, 0, 0, DateTimeKind.Utc), Status = "Picked Up", Location = "Los Angeles, CA" },
                new StatusUpdate { Timestamp = new DateTime(2026, 6, 2, 14, 30, 0, DateTimeKind.Utc), Status = "Departed Facility", Location = "Phoenix, AZ" },
                new StatusUpdate { Timestamp = new DateTime(2026, 6, 3, 6, 15, 0, DateTimeKind.Utc), Status = "In Transit", Location = "Memphis, TN" },
            ]
        },
        ["TRK-2002"] = new Shipment
        {
            TrackingNumber = "TRK-2002",
            Status = "Out for Delivery",
            Location = "Seattle, WA",
            EstimatedDelivery = new DateTime(2026, 6, 3, 18, 0, 0, DateTimeKind.Utc),
            Updates =
            [
                new StatusUpdate { Timestamp = new DateTime(2026, 5, 30, 10, 0, 0, DateTimeKind.Utc), Status = "Picked Up", Location = "Portland, OR" },
                new StatusUpdate { Timestamp = new DateTime(2026, 6, 1, 9, 0, 0, DateTimeKind.Utc), Status = "Arrived at Hub", Location = "Tacoma, WA" },
                new StatusUpdate { Timestamp = new DateTime(2026, 6, 3, 7, 0, 0, DateTimeKind.Utc), Status = "Out for Delivery", Location = "Seattle, WA" },
            ]
        },
        ["TRK-3003"] = new Shipment
        {
            TrackingNumber = "TRK-3003",
            Status = "Delivered",
            Location = "New York, NY",
            EstimatedDelivery = new DateTime(2026, 6, 2, 12, 0, 0, DateTimeKind.Utc),
            Updates =
            [
                new StatusUpdate { Timestamp = new DateTime(2026, 5, 28, 11, 0, 0, DateTimeKind.Utc), Status = "Picked Up", Location = "Chicago, IL" },
                new StatusUpdate { Timestamp = new DateTime(2026, 5, 29, 16, 0, 0, DateTimeKind.Utc), Status = "In Transit", Location = "Cleveland, OH" },
                new StatusUpdate { Timestamp = new DateTime(2026, 5, 31, 8, 45, 0, DateTimeKind.Utc), Status = "Arrived at Hub", Location = "Newark, NJ" },
                new StatusUpdate { Timestamp = new DateTime(2026, 6, 2, 10, 30, 0, DateTimeKind.Utc), Status = "Delivered", Location = "New York, NY" },
            ]
        }
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);
        Seeds.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_f586a0f00ea34dafb36bbe1bd8901ceb.Client.Models
@using sv_f586a0f00ea34dafb36bbe1bd8901ceb.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (_loading)
{
    <div class="d-flex align-items-center gap-2 my-4">
        <div class="spinner-border spinner-border-sm" role="status"></div>
        <span>Loading shipment <strong>@TrackingNumber</strong>&hellip;</span>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger my-4" role="alert">
        <p class="mb-2">@_errorMessage</p>
        <button class="btn btn-outline-danger btn-sm" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is null)
{
    <div class="alert alert-warning my-4" role="alert">
        Shipment <strong>@TrackingNumber</strong> was not found.
    </div>
}
else
{
    <div class="card my-4">
        <div class="card-header">
            <h4 class="mb-0">Shipment @_shipment.TrackingNumber</h4>
        </div>
        <div class="card-body">
            <dl class="row mb-0">
                <dt class="col-sm-4">Status</dt>
                <dd class="col-sm-8">@_shipment.Status</dd>

                <dt class="col-sm-4">Current Location</dt>
                <dd class="col-sm-8">@_shipment.Location</dd>

                <dt class="col-sm-4">Estimated Delivery</dt>
                <dd class="col-sm-8">@_shipment.EstimatedDelivery.ToString("f")</dd>
            </dl>
        </div>
    </div>

    <h5>Status History</h5>
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Date &amp; Time</th>
                <th>Status</th>
                <th>Location</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var update in _shipment.Updates)
            {
                <tr>
                    <td>@update.Timestamp.ToString("g")</td>
                    <td>@update.Status</td>
                    <td>@update.Location</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private Shipment? _shipment;
    private bool _loading;
    private string? _errorMessage;

    private CancellationTokenSource? _cts;
    private string? _loadedTrackingNumber;

    protected override async Task OnParametersSetAsync()
    {
        if (string.Equals(_loadedTrackingNumber, TrackingNumber, StringComparison.OrdinalIgnoreCase) && _errorMessage is null)
            return;

        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request
        await CancelPendingRequestAsync();

        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        _loading = true;
        _errorMessage = null;
        _shipment = null;
        _loadedTrackingNumber = TrackingNumber;

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Navigation changed or component disposed — silently stop.
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong while loading the shipment. Please try again.";
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task RetryAsync()
    {
        _errorMessage = null;
        await LoadShipmentAsync();
    }

    private async ValueTask CancelPendingRequestAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
            _cts = null;
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }
}

